import hashlib, json
from pathlib import Path
root = Path('products/services/open-software-tenders/refresh-20261114')
records = []
for path in sorted(root.glob('source-*.json')):
    raw = path.read_bytes()
    package = json.loads(raw)
    for release in package.get('releases', []):
        tender = release.get('tender') or {}
        records.append({'source_file': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'ocid': release.get('ocid'), 'release_id': release.get('id'), 'release_date': release.get('date'), 'tags': release.get('tag'), 'status_at_capture': tender.get('status'), 'submission_deadline_at_capture': (tender.get('tenderPeriod') or {}).get('endDate'), 'title': tender.get('title'), 'document_ids': [doc.get('id') for doc in tender.get('documents', [])]})
assert records, 'No release records decoded from the selected source packages'
result = {'records': records, 'scope': 'Historical captures for candidate selection. Verify present status and deadline in an official source before treating any window as open. Different release IDs are comparable only after confirming the same procurement and scope.'}
out = Path('products/services/tender-amendment-brief/source-inventory.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
